const x = BigInt(require('readline').createInterface({ input: process.stdin, output: process.stdout }).on('line', (line) => {
    const x = BigInt(line.trim());
    let rem = ((x % 360n) + 360n) % 360n;
    let bestDev = 360n;
    let bestK = 0n;
    for (let k = 0n; k < 4n; k++) {
        let total = (rem + 90n * k) % 360n;
        let dev = total <= 180n ? total : 360n - total;
        if (dev < bestDev || (dev === bestDev && k < bestK)) {
            bestDev = dev;
            bestK = k;
        }
    }
    console.log(bestK.toString());
    process.exit(0);
}));
